// Deterministic Chrome Web Store asset generator for ToPath Saver.
// Uses ONLY existing deps (sharp) + Node builtins. No new packages, no network.
// Real UI captures come from docs/screenshots (generated by the Playwright stand on the real build).
// Run: node scripts/store-assets.mjs
import fs from 'node:fs';
import path from 'node:path';
import sharp from 'sharp';

const OUT = 'docs/store/assets';
const SHOTS = 'docs/screenshots';
const PUBLIC_ICON = 'public/icon/128.png';
const SRC_ICON = 'assets/icon.svg';

const PAPER = '#F9F8F7';
const TEXT = '#2C2C2B';
const BLUE = '#2783DE';
const DARK = '#191919';
const WHITE = '#FFFFFF';
const BORDER_LIGHT = '#E7E6E4';
const BORDER_DARK = '#303030';
const FONT = 'Arial, Helvetica, sans-serif';

fs.mkdirSync(OUT, { recursive: true });

const esc = (s) => s.replace(/&/g, '&').replace(/</g, '<').replace(/>/g, '>');

const frame = (w, h, bg, border) =>
  `<rect x="1" y="1" width="${w - 2}" height="${h - 2}" fill="${bg}" stroke="${border}" stroke-width="2"/>`;

const svgDoc = (w, h, inner) =>
  Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}">${inner}</svg>`);

function textBlock(lines, { x, size, color, weight = 400, baseline, step }) {
  const out = [];
  let y = baseline;
  for (const ln of lines) {
    out.push(
      `<text x="${x}" y="${y}" font-family="${FONT}" font-size="${size}" font-weight="${weight}" fill="${color}">${esc(ln)}</text>`,
    );
    y += step;
  }
  return out.join('');
}

async function meta(file, label = file) {
  const m = await sharp(file).metadata();
  console.log(`${label} ${m.width}x${m.height} ${m.format}`);
}

// --- 1280x800 store screenshots ---------------------------------------------
const W = 1280;
const H = 800;

const slides = [
  {
    file: '01-folders.png',
    bg: PAPER,
    border: BORDER_LIGHT,
    color: TEXT,
    hSize: 48,
    bSize: 28,
    tx: 64,
    heading: ['Your downloads.', 'Your folders.'],
    body: ['Choose a folder in two clicks.', 'Files stay inside Downloads.'],
    captures: [{ src: '../store/captures/m01-images-selected-full.png', left: 680, top: 100 }],
  },
  {
    file: '02-auto-sort.png',
    bg: PAPER,
    border: BORDER_LIGHT,
    color: TEXT,
    hSize: 48,
    bSize: 28,
    tx: 64,
    heading: ['Sort by file type.'],
    body: ['Documents, images, video and archives.'],
    captures: [{ src: 'm02-auto-sort.png', left: 680, top: 120 }],
  },
  {
    file: '03-icon-styles.png',
    bg: PAPER,
    border: BORDER_LIGHT,
    color: TEXT,
    hSize: 44,
    bSize: 26,
    tx: 64,
    heading: ['Make it yours.'],
    body: ['Four icon styles.', 'Light and dark themes.'],
    captures: [
      { src: 'm06-icons-lucide.png', left: 520, top: 100 },
      // TASK x880 conflicts with its 64px safe area: 880+340=1220 >1216.
      { src: 'm06-icons-fluent3d.png', left: 876, top: 100 },
    ],
  },
  {
    file: '04-dark.png',
    bg: DARK,
    border: BORDER_DARK,
    color: WHITE,
    hSize: 48,
    bSize: 28,
    tx: 64,
    heading: ['One download.', 'Or your next batch.'],
    body: ['One-time mode returns to', 'your previous folder.'],
    captures: [{ src: '../store/captures/m05-main-dark-full.png', left: 680, top: 100 }],
  },
];

async function renderSlide(s) {
  const hLine = Math.round(s.hSize * 1.2);
  const bLine = Math.round(s.bSize * 1.42);
  const gap = 28;
  const total = s.heading.length * hLine + gap + s.body.length * bLine;
  const top = Math.round(H / 2 - total / 2);

  const headBase = top + Math.round(s.hSize * 0.82);
  const afterHeading = top + s.heading.length * hLine;
  const bodyBase = afterHeading + gap + Math.round(s.bSize * 0.85);

  const inner =
    frame(W, H, s.bg, s.border) +
    textBlock(s.heading, { x: s.tx, size: s.hSize, color: s.color, weight: 700, baseline: headBase, step: hLine }) +
    `<rect x="${s.tx}" y="${afterHeading + 8}" width="64" height="6" rx="3" fill="${BLUE}"/>` +
    textBlock(s.body, { x: s.tx, size: s.bSize, color: s.color, weight: 400, baseline: bodyBase, step: bLine });

  const comps = [{ input: svgDoc(W, H, inner), top: 0, left: 0 }];
  for (const c of s.captures) comps.push({ input: path.join(SHOTS, c.src), left: c.left, top: c.top });

  await sharp({ create: { width: W, height: H, channels: 4, background: s.bg } })
    .composite(comps)
    .png()
    .toFile(path.join(OUT, s.file));
  await meta(path.join(OUT, s.file));
}

// --- 440x280 small promo ----------------------------------------------------
async function renderPromo() {
  const w = 440;
  const h = 280;
  const icon = await sharp(PUBLIC_ICON)
    .resize(96, 96, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .png()
    .toBuffer();
  const inner =
    frame(w, h, PAPER, BORDER_LIGHT) +
    `<text x="152" y="128" font-family="${FONT}" font-size="30" font-weight="700" fill="${TEXT}">ToPath Saver</text>` +
    `<text x="152" y="162" font-family="${FONT}" font-size="20" font-weight="400" fill="${TEXT}">Downloads, organized.</text>` +
    `<rect x="152" y="178" width="48" height="5" rx="2.5" fill="${BLUE}"/>`;
  await sharp({ create: { width: w, height: h, channels: 4, background: PAPER } })
    .composite([
      { input: svgDoc(w, h, inner), top: 0, left: 0 },
      { input: icon, left: 32, top: 88 },
    ])
    .png()
    .toFile(path.join(OUT, 'small-promo.png'));
  await meta(path.join(OUT, 'small-promo.png'));
}

// --- 128x128 store icon -----------------------------------------------------
async function alphaBBox(file) {
  const { data, info } = await sharp(file).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const { width, height, channels } = info;
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const a = data[(y * width + x) * channels + 3];
      if (a > 8) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }
  if (maxX < 0) return { w: 0, h: 0, minX: 0, minY: 0, maxX: 0, maxY: 0 };
  return { w: maxX - minX + 1, h: maxY - minY + 1, minX, minY, maxX, maxY };
}

async function renderIcon() {
  const bbox = await alphaBBox(PUBLIC_ICON);
  const compliant =
    bbox.w >= 80 && bbox.w <= 112 && bbox.h >= 80 && bbox.h <= 112 && bbox.minX >= 8 && bbox.minY >= 8;
  if (compliant) {
    fs.copyFileSync(PUBLIC_ICON, path.join(OUT, 'icon-128.png'));
    console.log(`icon-128.png copy of ${PUBLIC_ICON}; art bbox ${bbox.w}x${bbox.h} at (${bbox.minX},${bbox.minY}) -> compliant`);
  } else {
    const art = await sharp(SRC_ICON, { density: 384 })
      .resize(96, 96, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
      .png()
      .toBuffer();
    await sharp({ create: { width: 128, height: 128, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } } })
      .composite([{ input: art, left: 16, top: 16 }])
      .png()
      .toFile(path.join(OUT, 'icon-128.png'));
    console.log(`icon-128.png built from ${SRC_ICON}; prior art bbox ${bbox.w}x${bbox.h} -> resized to 96x96 centered`);
  }
  await meta(path.join(OUT, 'icon-128.png'));
}

for (const s of slides) await renderSlide(s);
await renderPromo();
await renderIcon();
console.log('store-assets: done -> ' + OUT);